css:
/* 写真を切らずに文字面を作る（境界は縦線1本） */
.row{position:relative; min-height:300px; background:url(photo.jpg) center/cover}
.row__text{width:50%; height:100%; padding:40px; color:#fff;
  background:rgba(126,192,222,.86)}

/* デュオトーンで片側へ溶かす */
.sec{background:linear-gradient(90deg,rgba(184,116,15,.15) 0%,#b8740f 58%),
                url(portrait.jpg) left center/cover;
     background-blend-mode:multiply}

/* 範囲だけ沈めて注記を重ねる（未確定・準備中） */
.tentative{position:relative; grid-column:2/7; border-radius:10px;
  outline:1px dashed #9aa2a8; outline-offset:-1px}
.tentative::before{content:""; position:absolute; inset:0; background:rgba(255,255,255,.62)}
.tentative .note{position:absolute; inset:0; display:grid; place-content:center; text-align:center}

/* またいだ部分だけ下地を透かす */
.date{position:absolute; left:-36px; top:50%; translate:0 -50%;
  width:72px; aspect-ratio:1; border-radius:50%;
  background:rgba(125,145,155,.38); color:#fff;
  display:grid; place-content:center; text-align:center}

/* 面を敷かない版：影だけで明るい写真に白抜きを乗せる */
figcaption{position:absolute; left:10px; bottom:8px; color:#fff;
  text-shadow:0 1px 4px rgba(0,0,0,.65)}
